import{_ as n,K as o,a as p,c as s,ac as t,q as i,b as e,k as l}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"算法契约、不变量与反例","description":"以二分下界解释输入约束、终止、预处理成本，再对照带权最短路与贪心反例。","frontmatter":{"title":"算法契约、不变量与反例","description":"以二分下界解释输入约束、终止、预处理成本，再对照带权最短路与贪心反例。","showdocs":{"topics":[{"id":"algorithms","title":"算法","link":"/topics/algorithms/"}],"kind":"问题与数据结构","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"算法与数据结构：模型与推演","summary":"以二分下界解释输入约束、终止、预处理成本，再对照带权最短路与贪心反例。","status":"active","related":[{"title":"算法推演与练习","link":"/principles/algorithms/exercises/application","kind":"算法推演","scope":"general","audience":"general"},{"title":"Go 算法与容器实践：遍历、排序、递推与堆","link":"/principles/algorithms/exercises/go-interview-algorithm","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组","link":"/principles/algorithms/exercises/leetcode-arrary","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 两数之和至移除元素","link":"/principles/algorithms/exercises/leetcode-arrary-part-01","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 搜索插入位置至完整入口与预期结果","link":"/principles/algorithms/exercises/leetcode-arrary-part-02","kind":"算法推演","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"principles/algorithms/reasoning-and-correctness.md","filePath":"principles/algorithms/reasoning-and-correctness.md"}'),h={name:"principles/algorithms/reasoning-and-correctness.md"};function d(c,a,g,m,u,I){const r=o("Mermaid");return p(),s("div",null,[a[0]||(a[0]=t('<h1 id="算法契约、不变量与反例" tabindex="-1">算法契约、不变量与反例 <a class="header-anchor" href="#算法契约、不变量与反例" aria-label="Permalink to &quot;算法契约、不变量与反例&quot;">​</a></h1><h2 id="part-1" tabindex="-1">二分查找、线性结构与循环不变量 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;二分查找、线性结构与循环不变量 {#part-1}&quot;">​</a></h2><p><span id="part-1-算法与数据结构-问题、表示与约束"></span></p><p>前置：能阅读整数数组、比较操作与循环，理解半开区间 [lo,hi)；Python 3.10+ 仅供手推或自跑完整下界程序。教学范围为比较模型；Python 3.10+；半开区间。核对日期2026-10-17。示例未执行，本轮没有安装依赖、生成协议代码、启动服务或浏览器预览。完整文件与输入见<a href="/principles/algorithms/exercises/application">下界程序、输入与逐步练习</a>；推演结论只适用于写明的模型。</p><h3 id="part-1-contract" tabindex="-1">二分查找输入契约 <a class="header-anchor" href="#part-1-contract" aria-label="Permalink to &quot;二分查找输入契约 {#part-1-contract}&quot;">​</a></h3><p>二分查找输入契约要求有序数组按同一比较规则排列。下界是第一个不小于目标的下标，目标不存在时也能返回插入点；查找相等元素还须检查下标小于长度。一次查询先排序会花费更多工作，不能只报告查找环节。</p><h3 id="part-1-structure" tabindex="-1">数组与链表的选择 <a class="header-anchor" href="#part-1-structure" aria-label="Permalink to &quot;数组与链表的选择 {#part-1-structure}&quot;">​</a></h3><p>数组与链表的选择取决于操作序列。随机访问适合连续数组；在数组中间插入要移动后缀。链表只有持有节点时才能常数时间插入，先按下标寻找仍需线性时间，还付出指针与分配开销。</p><h3 id="part-1-invariant" tabindex="-1">二分循环不变量 <a class="header-anchor" href="#part-1-invariant" aria-label="Permalink to &quot;二分循环不变量 {#part-1-invariant}&quot;">​</a></h3><p>对 [1,3,3,8] 求目标 3 的下界，最初 [lo,hi)=[0,4)。mid=2 时值为 3，把 hi 收到 2；mid=1 时仍为 3，再收至 1；mid=0 时值为 1，把 lo 推到 1。左右边界汇合后，左边全小于 3，右边全不小于 3，所以位置 1 正是最左合法插入点。</p>',10)),i(r,{source:"Zmxvd2NoYXJ0IFRECiAgICBBWyLmnKrnn6XljLrpl7QgWzAsNCnvvIznm67moIcgMyJdIC0tPiBCWyJtaWQ9Mu+8jOWAvCAz77yaaGk9MiJdCiAgICBCIC0tPiBDWyJtaWQ9Me+8jOWAvCAz77yaaGk9MSJdCiAgICBDIC0tPiBEWyJtaWQ9MO+8jOWAvCAx77yabG89MSJdCiAgICBEIC0tPiBFWyJsbz1oaT0x77yb5bem6L655pivIDHvvIzlj7PovrnmmK8gMywzLDgiXQo="}),a[1]||(a[1]=t('<p>二分循环不变量把位置分为三段：左侧所有值小于目标，右侧所有值不小于目标，中间半开区间尚待判断。初始两侧为空；遇到小值令lo=mid+1，否则令hi=mid，两个已知区域都保持成立。</p><h4 id="part-1-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-1-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-1-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://www.hello-algo.com/en/chapter_searching/binary_search/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://www.hello-algo.com/chapter_searching/binary_search/" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li></ul><h2 id="part-2" tabindex="-1">二分终止、复杂度与最短路边界 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;二分终止、复杂度与最短路边界 {#part-2}&quot;">​</a></h2><p><span id="part-2-算法与数据结构-机制、交互与代价"></span></p><h3 id="part-2-termination" tabindex="-1">二分为什么终止 <a class="header-anchor" href="#part-2-termination" aria-label="Permalink to &quot;二分为什么终止 {#part-2-termination}&quot;">​</a></h3><p>用只剩一个元素的区间 [2,3) 检查更新：mid=2，若值小于目标，lo=mid+1=3；否则 hi=mid=2。两条分支都使长度从 1 变成 0。错误的 lo=mid 会保持 [2,3) 不变，条件仍成立，形成死循环。</p>',7)),i(r,{source:""}),a[2]||(a[2]=e("p",null,"二分为什么终止要看区间长度hi-lo。lo小于hi时中点严格小于hi，每次更新至少排除一个位置，使非负长度严格递减。若把lo改成mid，在只剩一个元素时可能不前进。空数组初始长度为零直接结束。",-1)),a[3]||(a[3]=e("h3",{id:"part-2-complexity",tabindex:"-1"},[l("复杂度与预处理成本 "),e("a",{class:"header-anchor",href:"#part-2-complexity","aria-label":'Permalink to "复杂度与预处理成本 {#part-2-complexity}"'},"​")],-1)),a[4]||(a[4]=e("p",null,"复杂度与预处理成本必须分开：有序随机访问数组的下界查询比较次数为对数，额外空间为常数；本例输入验证扫描为线性，所以完整程序单次工作为线性。反复查询可把验证移到数据导入边界，但须保证随后不被乱序修改。",-1)),a[5]||(a[5]=e("h3",{id:"part-2-graphs",tabindex:"-1"},[l("广度搜索最短路边界 "),e("a",{class:"header-anchor",href:"#part-2-graphs","aria-label":'Permalink to "广度搜索最短路边界 {#part-2-graphs}"'},"​")],-1)),a[6]||(a[6]=e("p",null,"补充反例：S→T 权重 10，S→A 与 A→T 权重均为 1。BFS 按边数会先发现直达 T 的一条边，但总代价 10 大于经过 A 的 2。按层最早发现只证明边数最少，不证明任意权重之和最少。",-1)),i(r,{source:"Zmxvd2NoYXJ0IFRECiAgICBTWyJTIl0gLS0+fCLkuIDmnaHovrnvvIzmnYPph40gMTAifCBUWyJUIl0KICAgIFMgLS0+fCLmnYPph40gMSJ8IEFbIkEiXQogICAgQSAtLT58Iuadg+mHjSAxInwgVAo="}),a[7]||(a[7]=t('<p>广度搜索最短路边界是无权图或各边权重相同。队列按层处理，首次发现时标记避免重复入队。权重不同会破坏首次到达最优的性质；负边更不能套Dijkstra，先检查模型再选择算法。</p><h4 id="part-2-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-2-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-2-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://www.hello-algo.com/en/chapter_searching/binary_search/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://www.hello-algo.com/chapter_searching/binary_search/" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li></ul><h2 id="part-3" tabindex="-1">算法反例、复杂度取舍与参考 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;算法反例、复杂度取舍与参考 {#part-3}&quot;">​</a></h2><p><span id="part-3-算法与数据结构-反例、取舍与原文"></span></p><h3 id="part-3-counterexample" tabindex="-1">贪心与动态规划反例 <a class="header-anchor" href="#part-3-counterexample" aria-label="Permalink to &quot;贪心与动态规划反例 {#part-3-counterexample}&quot;">​</a></h3><p>dp[1..6] 依次为 1、2、1、1、2、2。计算 dp[6] 时，最后一枚分别为 1、3、4，候选是 dp[5]+1=3、dp[3]+1=2、dp[2]+1=3。枚举最后一步覆盖全部合法方案，取最小才得到 3+3；不能把“优先最大面额”当作通用定理。</p>',7)),i(r,{source:"Zmxvd2NoYXJ0IFRECiAgICBBWyLnm67moIcgNiJdIC0tPiBCWyLotKrlv4PlhYjmi78gNO+8jOS9mSAyIl0KICAgIEIgLS0+IENbIuWGjeaLvyAxKzHvvJrlhbEgMyDmnpoiXQogICAgQSAtLT4gRFsiRFAg5pyA5ZCO5LiA5p6a5Li6IDPvvIzkvZkgMyJdCiAgICBEIC0tPiBFWyLlho3mi78gM++8muWFsSAyIOaemiJdCg=="}),a[8]||(a[8]=t('<p>贪心与动态规划反例可用硬币1、3、4组成6：每次拿最大硬币得到4+1+1，最优却是3+3。动态规划定义dp[s]为组成s的最少数量，初值dp[0]=0，不可达为无穷，再枚举最后一枚；不能因少数样例成功就宣称贪心正确。</p><h3 id="part-3-review" tabindex="-1">算法证据复核清单 <a class="header-anchor" href="#part-3-review" aria-label="Permalink to &quot;算法证据复核清单 {#part-3-review}&quot;">​</a></h3><p>算法证据复核清单先写输入约束和不变量，再给终止度量与资源界。反例至少包括空输入、重复元素、极端目标和违反前提；测试不能代替证明，但能及时揭示实现与证明不一致。稳定性、字节与字符、溢出分别属于不同契约。</p><h3 id="part-3-sources" tabindex="-1">算法原文与旧文索引 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;算法原文与旧文索引 {#part-3-sources}&quot;">​</a></h3><p>算法原文与旧文索引用中文与英文Hello Algo对照区间写法，新课自行推导下界不变量。旧算法单题保留各自实现与锚点；平衡树旋转不是完整AVL，哈夫曼代价函数不是完整编码器，不能将旧单函数等同于完整项目。</p><h4 id="part-3-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-3-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-3-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://www.hello-algo.com/en/chapter_searching/binary_search/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://www.hello-algo.com/chapter_searching/binary_search/" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li><li><a href="/principles/algorithms/analysis/overview">相关既有参考</a>：原URL与专业范围保留；历史案例不能自动代表当前实现。</li></ul>',7))])}const _=n(h,[["render",d]]);export{b as __pageData,_ as default};
